Hashmap uses hash of key that gets converted to index for Entry array to store this entry in Entry[] array.
Now this Entry[] array points to first entry in that bucket, Now in case of collisions ie entry landing to same bucket then we create linked list and assign that entry to last entry's next and At the time of getting entry we use equals on key to get appropriate entry..
So HashMap uses array of entries for Bucket and linked list is to store each entry.
Now starting from JDK 8 , this linked list to store entries is changed.. so until some threshold we use linked list but after that we use balanced tree so now worst case scenario to find a node is changed from O(n) to O(log n)
public class HashMap&lt;K, V&gt; extends AbstractMap&lt;K, V&gt; implements Map&lt;K, V&gt;, Cloneable, Serializable
{
	/**
	 * The default initial capacity - MUST be a power of two.
	 */
	static final int DEFAULT_INITIAL_CAPACITY = 16;
	/**
	 * The maximum capacity, used if a higher value is implicitly specified by
	 * either of the constructors with arguments. MUST be a power of two &lt;=
	 * 1&lt;&lt;30.
	 */
	static final int MAXIMUM_CAPACITY = 1 &lt;&lt; 30;
	/**
	 * The load factor used when none specified in constructor.
	 */
	static final float DEFAULT_LOAD_FACTOR = 0.75f;
	/**
	 * The table, resized as necessary. Length MUST Always be a power of two.
	 */
	transient Entry[] table;
	/**
	 * The number of key-value mappings contained in this map.
	 */
	transient int size;
	/**
	 * The next size value at which to resize (capacity * load factor).
	 *&nbsp;
	 * @serial
	 */
	int threshold;
	/**
	 * The load factor for the hash table.
	 *
	 * @serial
	 */
	final float loadFactor;
	/**
	 * The number of times this HashMap has been structurally modified
	 * Structural modifications are those that change the number of mappings in
	 * the HashMap or otherwise modify its internal structure (e.g., rehash).
	 * This field is used to make iterators on Collection-views of the HashMap
	 * fail-fast. (See ConcurrentModificationException).
	 */
	transient volatile int modCount;
public V get(Object key)
	{
		if (key == null)
			return getForNullKey();
		int hash = hash(key.hashCode());
		for (Entry&lt;K, V&gt; e = table[indexFor(hash, table.length)]; e != null; e = e.next)
		{
			Object k;
			if (e.hash == hash &amp;&amp; ((k = e.key) == key || key.equals(k)))
				return e.value;
		}
		return null;
	}

	/**
	 * Applies a supplemental hash function to a given hashCode, which defends
	 * against poor quality hash functions. This is critical because HashMap
	 * uses power-of-two length hash tables, that otherwise encounter collisions
	 * for hashCodes that do not differ in lower bits. Note: Null keys always
	 * map to hash 0, thus index 0.
	 */
	static int hash(int h)
	{
		// This function ensures that hashCodes that differ only by
		// constant multiples at each bit position have a bounded
		// number of collisions (approximately 8 at default load factor).
		h ^= (h &gt;&gt;&gt; 20) ^ (h &gt;&gt;&gt; 12);
		return h ^ (h &gt;&gt;&gt; 7) ^ (h &gt;&gt;&gt; 4);
	}

	/**
	 * Returns index for hash code h.
	 */
	static int indexFor(int h, int length)
	{
		return h &amp; (length - 1);
	}

	/**
	 * Offloaded version of get() to look up null keys. Null keys map to index
	 * 0. This null case is split out into separate methods for the sake of
	 * performance in the two most commonly used operations (get and put), but
	 * incorporated with conditionals in others.
	 */
	private V getForNullKey()
	{
		for (Entry&lt;K, V&gt; e = table[0]; e != null; e = e.next)
		{
			if (e.key == null)
				return e.value;
		}
		return null;
	}

	final Entry&lt;K, V&gt; getEntry(Object key)
	{
		int hash = (key == null) ? 0 : hash(key.hashCode());
		for (Entry&lt;K, V&gt; e = table[indexFor(hash, table.length)]; e != null; e = e.next)
		{
			Object k;
			if (e.hash == hash &amp;&amp; ((k = e.key) == key || (key != null &amp;&amp; key.equals(k))))
				return e;
		}
		return null;
	}

	public V put(K key, V value)
	{
		if (key == null)
			return putForNullKey(value);
		int hash = hash(key.hashCode());
		int i = indexFor(hash, table.length);
		for (Entry&lt;K, V&gt; e = table[i]; e != null; e = e.next)
		{
			Object k;
			if (e.hash == hash &amp;&amp; ((k = e.key) == key || key.equals(k)))
			{
				V oldValue = e.value;
				e.value = value;
				e.recordAccess(this);
				return oldValue;
			}
		}
		modCount++;
		addEntry(hash, key, value, i);
		return null;
	}

	void addEntry(int hash, K key, V value, int bucketIndex)
	{
		Entry&lt;K, V&gt; e = table[bucketIndex];
		table[bucketIndex] = new Entry&lt;K, V&gt;(hash, key, value, e);
		if (size++ &gt;= threshold)
			resize(2 * table.length);
	}

	void resize(int newCapacity)
	{
		Entry[] oldTable = table;
		int oldCapacity = oldTable.length;
		if (oldCapacity == MAXIMUM_CAPACITY)
		{
			threshold = Integer.MAX_VALUE;
			return;
		}
		Entry[] newTable = new Entry[newCapacity];
		transfer(newTable);
		table = newTable;
		threshold = (int) (newCapacity * loadFactor);
	}

	void transfer(Entry[] newTable)
	{
		Entry[] src = table;
		int newCapacity = newTable.length;
		for (int j = 0; j &lt; src.length; j++)
		{
			Entry&lt;K, V&gt; e = src[j];
			if (e != null)
			{
				src[j] = null;
				do
				{
					Entry&lt;K, V&gt; next = e.next;
					int i = indexFor(e.hash, newCapacity);
					e.next = newTable[i];
					newTable[i] = e;
					e = next;
				}
				while (e != null);
			}
		}
	}

	private abstract class HashIterator&lt;E&gt; implements Iterator&lt;E&gt;
	{
		Entry&lt;K, V&gt; next; // next entry to return
		int expectedModCount; // For fast-fail
		int index; // current slot
		Entry&lt;K, V&gt; current; // current entry
		HashIterator()
		{
			expectedModCount = modCount;
			if (size &gt; 0)
			{ // advance to first entry
				Entry[] t = table;
				while (index &lt; t.length &amp;&amp; (next = t[index++]) == null)
					;
			}
		}
		public final boolean hasNext()
		{
			return next != null;
		}
		final Entry&lt;K, V&gt; nextEntry()
		{
			if (modCount != expectedModCount)
				throw new ConcurrentModificationException();
			Entry&lt;K, V&gt; e = next;
			if (e == null)
				throw new NoSuchElementException();
			if ((next = e.next) == null)
			{
				Entry[] t = table;
				while (index &lt; t.length &amp;&amp; (next = t[index++]) == null)
					;
			}
			current = e;
			return e;
		}
		public void remove()
		{
			if (current == null)
				throw new IllegalStateException();
			if (modCount != expectedModCount)
				throw new ConcurrentModificationException();
			Object k = current.key;
			current = null;
			HashMap.this.removeEntryForKey(k);
			expectedModCount = modCount;
		}
	}

	private final class ValueIterator extends HashIterator&lt;V&gt;
	{
		public V next()
		{
			return nextEntry().value;
		}
	}
	private final class KeyIterator extends HashIterator&lt;K&gt;
	{
		public K next()
		{
			return nextEntry().getKey();
		}
	}
	private final class EntryIterator extends HashIterator&lt;Map.Entry&lt;K, V&gt;&gt;
	{
		public Map.Entry&lt;K, V&gt; next()
		{
			return nextEntry();
		}
	}

	...
}

